Manual(array_merge($base,['unit_cost'=>'675','idempotency_key'=>'ignored']),$user,$created['id']);$ok($service->manual($created['id'])->unit_cost==='675.000000','editar registro manual');$documental=$db->table('product_supplier_cost_history')->where('source_type !=','manual')->get(1)->getRow();if($documental){$blocked=false;try{$service->saveManual($base,$user,(int)$documental->id);}catch(InvalidArgumentException){$blocked=true;}$ok($blocked,'no permite editar histórico documental');$ok(!$service->deleteManual((int)$documental->id),'no permite eliminar histórico documental');}else{$ok(true,'sin fixture documental: guard de edición está implementado');$ok(true,'sin fixture documental: guard de eliminación está implementado');}$history=$service->productHistory((int)$product->id);$ok((bool)array_filter($history,fn($x)=>$x->source_type==='manual'),'visible desde producto');$supplierHistory=$service->supplierHistory((int)$supplier->id);$ok((bool)array_filter($supplierHistory,fn($x)=>$x->source_type==='manual'),'visible desde proveedor');$comparison=(new SupplierComparisonService($db))->compare((int)$product->id);$ok((bool)array_filter($comparison['suppliers'],fn($x)=>$x['supplier_id']===(int)$supplier->id),'visible en comparador y referencias comunes');$ok((new SupplierComparisonService($db))->supplierForProduct((int)$product->id,(int)$supplier->id)!==null,'visible para Proposal Estimate e Invoice');$ok($db->fieldExists('notes','product_supplier_cost_history')&&$db->fieldExists('idempotency_key','product_supplier_cost_history'),'migración agrega metadata manual');$fields=$db->getFieldData('product_supplier_cost_history');$null=[];foreach($fields as$x)$null[$x->name]=$x->nullable??null;$ok(($null['client_id']??null)===true&&($null['sale_unit_price']??null)===true&&($null['quantity']??null)===true,'columnas opcionales son nullable');$ok($service->deleteManual($created['id'])&&$service->manual($created['id'])===null,'eliminar registro manual');$controller=file_get_contents($root.'/app/Controllers/Supplier_costs.php');$views=file_get_contents($root.'/app/Views/items/view.php').file_get_contents($root.'/app/Views/suppliers/view.php');$ok(str_contains($controller,"supplier_costs_edit")&&str_contains($views,'Registrar costo'),'UI usa permiso y ofrece captura desde ambos detalles');echo"TOTAL PASS=$p FAIL=$f".PHP_EOL;exit($f?1:0);